Apelido de Yaf_Loader::registerLocalNamespace.

  &reftitle.examples;

   Exemplo de Yaf_Loader::registerNamespace


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initLoader()
    {
        /* registerNamespace() é um apelido de registerLocalNamespace() */
        Yaf_Loader::getInstance()->registerNamespace(
            "Vendor",
            APPLICATION_PATH . "/library/Vendor"
        );
    }
}

/* new Vendor_Payment_Gateway() agora é procurada em
 * APPLICATION_PATH/library/Vendor/Payment/Gateway.php */
?>
